import{_ as l,l as r,o as a,c,v as o,p as i,x as t,d as T,i as n,S as s}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"GOT 与 PLT","description":"","frontmatter":{"title":"GOT 与 PLT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/got-plt.md","filePath":"cs/got-plt.md","lastUpdated":1789023840000}'),p={name:"cs/got-plt.md"};function _(L,e,P,h,O,m){const d=r("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="got-与-plt" tabindex="-1">GOT 与 PLT <a class="header-anchor" href="#got-与-plt" aria-label="Permalink to &quot;GOT 与 PLT&quot;">​</a></h1><div class="epigraph"><p>GOT 是可写的地址表；PLT 是每符号一小段桩，第一次跳进解析器，以后经 GOT 直达。延迟绑定把重定位从加载时刻挪到首次调用。</p><footer>—— 据 System V ABI；ELF 规范；Levine, Linkers and Loaders, 2000 整理</footer></div><p>上一课<a href="/cs/link-reloc">链接与重定位</a>把多个 <code>.o</code> 合成可执行或共享对象，并声明 PLT/GOT 的运行时跳板不在那一课。PIC 已要求外部访问走间接。本课不重做节合并。缺口是两张表的形状：GOT 条目存绝对地址；PLT 条目是可执行桩。加载器下一课才 <code>mmap</code> 并把延迟绑定跑起来；本课把编译/链接产物侧钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共享库里 <code>call printf</code> 在链接期不知道 <code>printf</code> 的最终虚址，且每个进程基址不同。GOT：链接器为符号分配槽，代码 <code>load t, GOT[printf]; jalr t</code>。启动时动态链接器填槽。若每个调用都走解析，启动慢。PLT：桩先 <code>jmp *GOT[printf]</code>；槽的初值指回桩的解析路径，解析器写完 GOT 再跳到真 <code>printf</code>。之后 GOT 已是真地址，桩变成一次间接跳。</p><p>缺口是这份跳板，不是再解析静态强符号。数据符号通常只走 GOT（或 copy reloc），没有 PLT。</p><h3 id="plt-不是函数的别名" tabindex="-1">PLT 不是函数的别名 <a class="header-anchor" href="#plt-不是函数的别名" aria-label="Permalink to &quot;PLT 不是函数的别名&quot;">​</a></h3><p>同一 <code>printf</code> 一个 PLT 项，多个调用点进同一桩。不要为每个调用点复制解析逻辑。位置无关下桩自己也用 GOT 自寻址。</p><p><span class="marginnote">System V ABI 的过程链接表。ELF <code>R_*_JUMP_SLOT</code> / <code>R_*_GLOB_DAT</code>。Levine 第 10 章动态链接。load-dynlink 课会从进程映像再讲一遍绑定时机；本课只建表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链接器为未决函数符号建 PLT+GOT 槽，为数据符号建 GOT 槽。重定位项指向槽而非 <code>.text</code> 里的立即数（PIC）。可执行文件对 <code>libc</code> 的引用默认走 PLT，除非 <code>-static</code>。</p>',11)),(a(),i(s,null,{default:t(()=>[n(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22call%20foo%22%5D%20--%3E%20PLT%5B%22PLT%20%E6%A1%A9%22%5D%0A%20%20PLT%20--%3E%20GOT%5B%22GOT%5Bfoo%5D%22%5D%0A%20%20GOT%20--%3E%7C%22%E6%9C%AA%E5%A1%AB%22%7C%20LD%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20LD%20--%3E%20GOT%0A%20%20GOT%20--%3E%7C%22%E5%B7%B2%E5%A1%AB%22%7C%20REAL%5B%22foo%20%E7%9C%9F%E5%9C%B0%E5%9D%80%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[T(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>立即绑定（<code>LD_BIND_NOW</code>）加载时填完所有 JUMP_SLOT，不要延迟。安全策略有时要求如此，本课点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GOT 必须可写、通常相对代码有固定位移（或经寄存器）。只读 GOT（RELRO）把填完后的表改只读，减少写 GOT 攻击面——安全课再收。本课要：表在数据段，桩在文本段。</p><p>不要把 PLT 当 C 的函数指针对象；函数指针值可能就是桩地址，比较与调用约定按 ABI。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不 <code>mmap</code>、不写 <code>ld.so</code> 算法细节、不处理 ifunc。后课默认：动态符号经 GOT/PLT。加载与动态链接把槽在运行时填上，并映射节进地址空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GOT 存地址；PLT 桩实现延迟绑定。</li><li>改写发生在 GOT，文本保持 PIC。</li><li>加载器下一课才跑；本课是表的布局。</li><li>出处：System V ABI；ELF；Levine, 2000。</li></ul>',8))])}const G=l(p,[["render",_]]);export{A as __pageData,G as default};
